/* @lc app=leetcode id=3266 lang=kotlin */ class Solution { fun getFinalState(nums: IntArray, k: Int, multiplier: Int): IntArray = if (multiplier == 1) nums else nums.max().toLong().let { mx -> 1_000_000_007L.let { M -> java.util.PriorityQueue<LongArray>(compareBy<LongArray>({ it[0] }, { it[1] })).also { pq -> nums.indices.forEach { pq.add(longArrayOf(nums[it].toLong(), it.toLong())) } }.let { pq -> generateSequence(k.toLong()) { rem -> if (rem > 0 && pq.peek()[0] < mx) (rem - 1).also { pq.add(pq.poll().let { e -> longArrayOf(e[0] * multiplier, e[1]) }) } else null }.last().let { rem -> pq.toList().sortedWith(compareBy<LongArray>({ it[0] }, { it[1] })).let { so -> IntArray(nums.size).also { res -> so.forEachIndexed { t, e -> res[e[1].toInt()] = (e[0] % M * java.math.BigInteger.valueOf(multiplier.toLong()).modPow(java.math.BigInteger.valueOf(rem / so.size + (if (t < rem % so.size) 1 else 0)), java.math.BigInteger.valueOf(M)).toLong() % M).toInt() } } } } } } } }